#!/usr/bin/env python3
"""Apply Delimt's keyboard, invitation, progress-arrow and icon update.

Run this file from your existing Delimt Codespace. Uses Python's standard
library and the project's existing Node dependencies. Does not start EAS.
"""
from __future__ import annotations

import base64
import copy
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile

APP_CHANGES = [{'old': 'import { configured, supabase } from "./src/lib/supabase";', 'new': 'import { configured, supabase } from "./src/lib/supabase";\nimport ProfileInvite from "./src/components/ProfileInvite";', 'label': 'Invitation import'}, {'old': '                accessibilityLabel={`Edit reason for ${habit.name}`}\n                onPress={() => edit(habit)}\n                style={{\n                  minWidth: 44,\n                  minHeight: 44,\n                  alignItems: "center",\n                  justifyContent: "center",\n                }}\n              >\n                <Pencil size={18} color={t.muted} />', 'new': '                accessibilityLabel={`View progress for ${habit.name}`}\n                onPress={openProgress}\n                style={{\n                  minWidth: 44,\n                  minHeight: 44,\n                  alignItems: "center",\n                  justifyContent: "center",\n                }}\n              >\n                <ArrowUpRight size={18} color={t.accent} />', 'label': 'Habit progress arrow'}, {'old': '              {habit.why || "Add your own reason for this habit."}\n            </Body>\n          </Card>', 'new': '              {habit.why || "Add your own reason for this habit."}\n            </Body>\n            <Pressable\n              accessibilityRole="button"\n              accessibilityLabel={`Edit reason for ${habit.name}`}\n              onPress={() => edit(habit)}\n              style={{ minHeight: 44, justifyContent: "center", alignSelf: "flex-start" }}\n            >\n              <Body muted style={text.small}>Edit this reason ↗</Body>\n            </Pressable>\n          </Card>', 'label': 'Separate reason editing'}, {'old': '      <Card>\n        <View style={layout.row}>\n          <Shield size={21} color={t.muted} />\n          <Heading style={{ fontSize: 19 }}>Privacy & account</Heading>', 'new': '      <ProfileInvite client={supabase} userId={user.id} preview={preview} colors={t} />\n      <Card>\n        <View style={layout.row}>\n          <Shield size={21} color={t.muted} />\n          <Heading style={{ fontSize: 19 }}>Privacy & account</Heading>', 'label': 'Profile invitation section'}, {'old': '  const [retryMessages, setRetry] = useState(null);\n  const alive = useRef(true),', 'new': '  const [retryMessages, setRetry] = useState(null);\n  const [inputHeight, setInputHeight] = useState(52);\n  const alive = useRef(true),', 'label': 'Chat composer size'}, {'old': '    setInput("");\n    setMessages(next);\n    ask(next);', 'new': '    setInput("");\n    setInputHeight(52);\n    setMessages(next);\n    ask(next);', 'label': 'Reset composer size after sending'}, {'old': '    <KeyboardAvoidingView\n      style={{ flex: 1 }}\n      behavior={Platform.OS === "ios" ? "padding" : undefined}\n    >\n      <View\n        style={[layout.between, { paddingHorizontal: 24, paddingBottom: 16 }]}', 'new': '    <KeyboardAvoidingView\n      style={{ flex: 1, minHeight: 0 }}\n      behavior={Platform.OS === "ios" ? "padding" : "height"}\n    >\n      <View\n        style={[layout.between, { paddingHorizontal: 24, paddingBottom: 16 }]}', 'label': 'Active Android keyboard avoidance'}, {'old': '        ref={scroll}\n        keyboardShouldPersistTaps="handled"\n        style={layout.chat}\n        contentContainerStyle={{ gap: 18, paddingBottom: 24 }}', 'new': '        ref={scroll}\n        keyboardShouldPersistTaps="handled"\n        keyboardDismissMode="on-drag"\n        style={[layout.chat, { flex: 1, minHeight: 0 }]}\n        onLayout={() => scroll.current?.scrollToEnd({ animated: false })}\n        contentContainerStyle={{ gap: 18, paddingBottom: 24 }}', 'label': 'Keep recent messages visible when the viewport changes'}, {'old': '              value={input}\n              onChangeText={setInput}\n              onSubmitEditing={send}\n              maxLength={1600}', 'new': '              value={input}\n              onChangeText={setInput}\n              multiline\n              scrollEnabled\n              submitBehavior="newline"\n              onContentSizeChange={(event) =>\n                setInputHeight(Math.max(52, Math.min(112, Math.ceil(event.nativeEvent.contentSize.height))))\n              }\n              maxLength={1600}', 'label': 'Grow the chat draft with its text'}, {'old': '                  flex: 1,\n                  borderColor: t.line,\n                  color: t.text,\n                  backgroundColor: t.card,\n                },\n              ]}\n            />\n            <Button\n              label="Send message"', 'new': '                  flex: 1,\n                  height: inputHeight,\n                  minHeight: 52,\n                  maxHeight: 112,\n                  paddingVertical: 12,\n                  textAlignVertical: "top",\n                  borderColor: t.line,\n                  color: t.text,\n                  backgroundColor: t.card,\n                },\n              ]}\n            />\n            <Button\n              label="Send message"', 'label': 'Keep the typing cursor visible'}]
PAYLOAD = {'assets/branding/delimt-icon.png': {'base64': '', 'sha256': '3d334670352d74c8b301cd2dcf8e5038c5874409c6dd6cebaba32708e523627a'}, 'assets/branding/delimt-adaptive.png': {'base64': '', 'sha256': 'eaf3c563b9c3af8b93e6caca83a1d2290353a7770fbd1ac03d08b90f24f5498d'}, 'assets/branding/delimt-monochrome.png': {'base64': '', 'sha256': '5b0c8ad93a44db0d6854b6180dab2a3ee44f2e92f73702e0cc4609fe3b88b5b1'}, 'assets/branding/delimt-store-icon.png': {'base64': '', 'sha256': '845f7c8861d7a1710731f2241a23f0eb6ef54972520b1749cd8f855434323fbd'}, 'assets/branding/delimt-logo.svg': {'base64': '', 'sha256': '84ba55aafb0545a3c396365b1ecfa318faea700feb78d0b28e2c222010f57beb'}, 'src/data/invitations.js': {'base64': '', 'sha256': '41e709ea39c574fd62a18e686d5d7792501fb13af713dc6b1158c50f797e2e21'}, 'src/components/ProfileInvite.jsx': {'base64': '', 'sha256': '2913fe7a7973becd797617badd515f001806776f7bd64cd0dc4a42195b2d6d56'}, 'tests/invitations.test.js': {'base64': '', 'sha256': 'a8b7648fcac34e8ccd65e866f7d83f545f9da2c93a4ec10ee8dbb1decb0c2b66'}}


def stop(message):
    raise RuntimeError(message)


def git(mobile, *args):
    return subprocess.run(["git", "-C", str(mobile), *args], text=True,
                          capture_output=True, check=False)


def ignored(mobile, relative):
    result = git(mobile, "check-ignore", "--no-index", "--quiet", "--", relative)
    if result.returncode not in (0, 1):
        stop("Could not check Git/build exclusions. No app files were changed.")
    return result.returncode == 0


def locate_mobile():
    for start in [Path.cwd(), Path(__file__).resolve().parent]:
        for parent in [start, *start.parents]:
            candidate = parent / "mobile"
            if (candidate / "App.jsx").is_file() and (candidate / "app.json").is_file():
                return candidate.resolve()
    stop("Open a terminal in your existing Delimt Codespace, then run this file again.")


def safe_path(mobile, relative):
    path = mobile / relative
    if Path(relative).is_absolute() or ".." in Path(relative).parts:
        stop("Invalid update path. No app files were changed.")
    if not path.resolve().is_relative_to(mobile):
        stop(f"{relative} points outside mobile/. No app files were changed.")
    for part in [path, *path.parents]:
        if part == mobile:
            break
        if part.is_symlink():
            stop(f"{relative} uses a symbolic link. No app files were changed.")
    return path


def transform_app(source):
    for change in APP_CHANGES:
        old, new = change["old"], change["new"]
        if new in source:
            if source.count(new) != 1:
                stop(change["label"] + " is duplicated. No app files were changed.")
            continue
        if source.count(old) != 1:
            stop(change["label"] + " differs from the reviewed source. Your existing app was preserved.")
        source = source.replace(old, new, 1)
    return source


def atomic_write(path, content):
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary = tempfile.mkstemp(prefix=".delimt-ui-", dir=path.parent)
    try:
        with os.fdopen(descriptor, "wb") as output:
            output.write(content)
        os.chmod(temporary, 0o644)
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def verify(mobile):
    parser = r'''
const fs = require("node:fs");
const {parse} = require("@babel/parser");
for (const file of ["App.jsx", "src/components/ProfileInvite.jsx", "src/data/invitations.js"]) {
  parse(fs.readFileSync(file, "utf8"), {sourceType: "module", plugins: ["jsx"]});
}
console.log("App and invitation source syntax verified.");
'''
    subprocess.run(["node", "-e", parser], cwd=mobile, check=True)
    tests = sorted(str(path.relative_to(mobile)) for path in (mobile / "tests").glob("*.test.js"))
    subprocess.run(["node", "--test", *tests], cwd=mobile, check=True)


def main():
    if len(sys.argv) != 1:
        stop("Run this updater without arguments. It prepares the combined changes and does not start a build.")
    if not shutil.which("git") or not shutil.which("node"):
        stop("Run this in your existing Codespace, where Git and Node are available.")
    mobile = locate_mobile()
    root = git(mobile, "rev-parse", "--show-toplevel")
    if root.returncode:
        stop("This is not your Git checkout. Open your existing Delimt Codespace.")
    if git(mobile, "branch", "--show-current").stdout.strip() != "android-foundation":
        stop("Open your android-foundation Codespace before applying this Android update.")
    for name in ["app.config.js", "app.config.ts", "app.config.mjs", "app.config.cjs"]:
        if (mobile / name).exists():
            stop(f"{name} controls your app settings. Its icon settings need integrating first; no app files changed.")

    app_path = safe_path(mobile, "App.jsx")
    app = app_path.read_text()
    if "./src/protection/useProtection" not in app or "./src/auth/useMobileAuth" not in app:
        stop("Use the working Codespace with app protection and the tested sign-in update. No app files changed.")
    for name in ["DelimtAccessibilityService.java", "DelimtProtectionModule.kt", "ProtectionPolicy.java", "ProtectionStore.java"]:
        relative = "modules/delimt-protection/android/src/main/java/expo/modules/delimtprotection/" + name
        if not safe_path(mobile, relative).is_file() or ignored(mobile, relative):
            stop("The native protection source is missing or excluded from the build. No app files changed.")
    if not (mobile / "node_modules/@supabase/supabase-js").is_dir():
        stop("Dependencies are missing. Run npm ci from mobile/, then run this updater again.")
    result = subprocess.run(["node", "-e", 'require.resolve("@babel/parser")'], cwd=mobile, text=True, capture_output=True)
    if result.returncode:
        stop("The project's existing build dependencies are incomplete. Run npm ci from mobile/ first.")

    manifest = safe_path(mobile, "app.json")
    config = json.loads(manifest.read_text())
    updated_config = copy.deepcopy(config)
    expo = updated_config.get("expo", {})
    if expo.get("android", {}).get("package") != "com.delimt.app":
        stop("This app has a different Android package. No app files changed.")
    schemes = expo.get("scheme", [])
    if isinstance(schemes, str): schemes = [schemes]
    if "delimt" not in schemes:
        stop("Keep the working delimt sign-in URL scheme. No app files changed.")
    native_manifest = "android/app/src/main/AndroidManifest.xml"
    if (mobile / native_manifest).exists() and not ignored(mobile, native_manifest):
        stop("The generated android/ project is included in the build. Its launcher resources need updating too; no app files changed.")

    android = expo["android"]
    adaptive = android.setdefault("adaptiveIcon", {})
    if not isinstance(adaptive, dict):
        stop("android.adaptiveIcon is not an object. No app files changed.")
    expo["icon"] = "./assets/branding/delimt-icon.png"
    android["icon"] = "./assets/branding/delimt-icon.png"
    android["softwareKeyboardLayoutMode"] = "resize"
    adaptive.update({"foregroundImage": "./assets/branding/delimt-adaptive.png",
                     "monochromeImage": "./assets/branding/delimt-monochrome.png",
                     "backgroundColor": "#0E100E"})
    adaptive.pop("backgroundImage", None)

    revised_app = transform_app(app)
    # App protection, session restoration, and save/retry behavior remain intact.
    def workspace(text):
        return text[text.index("function Workspace("):text.index("function HabitPicker(")]
    if workspace(app) != workspace(revised_app):
        stop("The protection workspace preservation check failed. No app files changed.")
    writes = {"App.jsx": revised_app.encode()}
    if updated_config != config:
        writes["app.json"] = (json.dumps(updated_config, indent=2, ensure_ascii=False) + "\n").encode()
    for relative, item in PAYLOAD.items():
        path = safe_path(mobile, relative)
        data = base64.b64decode(item["base64"], validate=True)
        if hashlib.sha256(data).hexdigest() != item["sha256"]:
            stop("The downloaded updater is incomplete. No app files changed.")
        if ignored(mobile, relative):
            stop(relative + " is excluded from uploads. No app files changed.")
        if path.exists() and (not path.is_file() or path.read_bytes() != data):
            stop(relative + " already contains different work. It was preserved; no app files changed.")
        writes[relative] = data

    pending = {relative: data for relative, data in writes.items()
               if not (mobile / relative).is_file() or (mobile / relative).read_bytes() != data}
    if pending:
        backup_parent = safe_path(mobile, ".expo/delimt-ui-backups")
        if not ignored(mobile, ".expo/delimt-ui-backups/preflight"):
            stop("mobile/.expo must be ignored so backups stay out of builds. No app files changed.")
        originals = {relative: (mobile / relative).read_bytes() if (mobile / relative).is_file() else None
                     for relative in pending}
        stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ")
        backup = backup_parent / stamp
        backup.mkdir(parents=True)
        for relative, data in originals.items():
            if data is not None:
                atomic_write(backup / relative, data)
        atomic_write(backup / "manifest.json", json.dumps({relative: data is not None for relative, data in originals.items()}, indent=2).encode())
        installed = []
        try:
            for relative, data in pending.items():
                path = mobile / relative
                current = path.read_bytes() if path.is_file() else None
                if current != originals[relative]:
                    stop(relative + " changed while the updater was running.")
                atomic_write(path, data)
                installed.append(relative)
            verify(mobile)
            for relative, data in pending.items():
                if (mobile / relative).read_bytes() != data:
                    stop("Could not verify " + relative + ".")
        except BaseException:
            for relative in reversed(installed):
                path = mobile / relative
                if path.is_file() and path.read_bytes() == pending[relative]:
                    if originals[relative] is None:
                        path.unlink()
                    else:
                        atomic_write(path, originals[relative])
            print("The update stopped. Generated changes were rolled back where unchanged; original files are backed up at:", backup, file=sys.stderr)
            raise
    else:
        verify(mobile)

    print("\nDELIMT UPDATE READY")
    print("Android chat: active keyboard avoidance and a growing multiline input.")
    print("Profile: Invite a friend, personal link, joined count and native sharing.")
    print("Home: progress arrow restored; reason editing has its own link.")
    print("Branding: Delimt launcher icons and matching store image included.")
    print("No EAS build, commit, push, or remote database change was started.")
    print("Next: build one standalone APK, then check typing with the keyboard open on your phone.")


if __name__ == "__main__":
    try:
        main()
    except (RuntimeError, OSError, ValueError, KeyError, TypeError, subprocess.CalledProcessError) as error:
        print("Update stopped:", error, file=sys.stderr)
        sys.exit(1)
